            widget.setMinimumHeight(20)
            widget.setMaximumHeight(22)
            widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            field_layout.addWidget(widget)
            host_layout.addWidget(field_box)
            return host

